const SCOPE=new URL('./',self.location.href),PREFIX=`who-works-${SCOPE.pathname}-`,CACHE=PREFIX+BUILD;
const allowed=new Set([...CORE,...OPTIONAL].map(file=>new URL(file,SCOPE).href));
const common=OPTIONAL.filter(file=>!file.startsWith('assets/home/'));
function canonical(request){
  let url;try{url=new URL(typeof request==='string'?request:request.url,SCOPE);}catch{return null;}
  if(url.origin!==SCOPE.origin||!url.pathname.startsWith(SCOPE.pathname))return null;
  if(url.pathname===SCOPE.pathname||url.pathname===new URL('index.html',SCOPE).pathname)return new URL('index.html',SCOPE).href;
  if(/\.(js|css)$/.test(url.pathname))url.search='?v='+BUILD;
  else if(url.pathname.startsWith(new URL('assets/',SCOPE).pathname))url.search='';
  return allowed.has(url.href)?url.href:null;
}
self.addEventListener('install',event=>{
  event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE.map(file=>new Request(new URL(file,SCOPE),{cache:'reload'})))).then(()=>self.skipWaiting()));
});
self.addEventListener('activate',event=>{
  event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));
});
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const key=canonical(event.request);if(!key)return;
  event.respondWith(fetch(event.request,event.request.mode==='navigate'?{cache:'no-cache'}:undefined).then(response=>{
    if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(key,copy)));}
    return response;
  }).catch(async()=>await(await caches.open(CACHE)).match(key)||new Response('Offline resource unavailable',{status:503})));
});
async function warm(files){
  const cache=await caches.open(CACHE),keys=[...new Set(files.filter(f=>typeof f==='string').map(canonical).filter(Boolean))];
  // Four fetches at a time; a failed optional image cannot invalidate the core.
  let index=0;
  await Promise.all(Array.from({length:4},async()=>{
    while(index<keys.length){const key=keys[index++];if(await cache.match(key))continue;
      try{const response=await fetch(new Request(key,{cache:'reload'}));if(response.ok)await cache.put(key,response);}catch{}
    }
  }));
}
self.addEventListener('message',event=>{
  if(event.data?.type==='warm-ui')event.waitUntil(warm(common));
  else if(['warm-home','warm-assets'].includes(event.data?.type)&&Array.isArray(event.data.files))event.waitUntil(warm(event.data.files.slice(0,256)));
});
